INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.76.0',
  '2026-08-06',
  'Пульт ТВ: подключение по коду с экрана',
  E'Раньше в пульт нужно было вписать адрес компьютера с агентом. Это неудобно: адрес надо знать, а роутер его ещё и меняет — и сохранённая приставка становилась мёртвой.\n\nТеперь приставка сама показывает код: крупно на экране запуска и мелко в углу во время просмотра. Наберите его в пульте — и всё. Код можно писать как угодно: с пробелом, дефисом, строчными буквами. Похожих знаков в нём нет — ноль с буквой «О» не перепутать.\n\nПриставка при этом запоминается: со второго раза подключение в одно нажатие, код больше не нужен. Имя приставки теперь постоянное и не зависит от адреса в сети, поэтому смена адреса роутером ничего не ломает.\n\nКод живёт, пока плеер открыт на телевизоре: выключили — код перестаёт действовать.',
  E'Комната больше НЕ адрес в локальной сети: его раздаёт DHCP, и после перезагрузки роутера комната становилась другой, а сохранённая на телефоне приставка — мёртвой. Теперь это имя машины плюс случайный хвост, лежит в кэше агента и переживает перезапуск и обновление.\n\nКоды живут в памяти шины (tvrelay), выдаются приставке при подключении к комнате и снимаются, когда из комнаты ушёл последний экран — иначе код остался бы годным для выключенного телевизора. Повторный вызов для той же комнаты отдаёт прежний код: перезагрузили страницу на телевизоре — код на экране меняться не должен.\n\nАлфавит без 0/O/1/I: код читают с телевизора и набирают на телефоне. Ввод нормализуется — регистр, пробелы и дефисы отбрасываются, ровно 8 знаков распознаются как код, иначе строка считается ключом комнаты (ручной режим сохранён).\n\nПульт помнит ключ комнаты отдельно от кода: переподключаться после обрыва надо по ключу, код к тому времени уже не набран.\n\nПроверено сквозным прогоном: 9 проверок на код (несуществующий отвергается, код стабилен при перезагрузке страницы, набор с пробелом и в нижнем регистре проходит, приставка попадает в список сохранённых, код умирает вместе с приставкой) плюс прежние 13 на релей — без регрессий.'
);
-- +goose StatementEnd

